/**
 * The account's state, for a client that keeps its own copy.
 *
 * ## Why cards come back whole rather than being replayed
 *
 * Card state is a pure function of the reviews applied to it, so in principle a
 * client could replay the log and arrive at the same place. It cannot, and the
 * reason is `applyFuzz`: the scheduler spreads due dates with an RNG so a
 * hundred cards learned on one evening do not all come back on the same one.
 * Two devices replaying the same reviews would land a day or two apart, forever,
 * with neither of them wrong.
 *
 * So the server's cards win. The log still comes down, because streaks,
 * retention and the per-kind breakdown are computed from it and a device that
 * only ever had its own half would under-report both.
 *
 * @generated from message mon.v1.PullStateResponse
 */
export type PullStateResponse = Message<"mon.v1.PullStateResponse"> & {
  /**
   * @generated from field: repeated mon.v1.Card cards = 1;
   */
  cards: Card[];

  /**
   * @generated from field: repeated mon.v1.StudyProfile profiles = 2;
   */
  profiles: StudyProfile[];

  /**
   * @generated from field: mon.v1.LanguageCode active_language = 3;
   */
  activeLanguage: LanguageCode;

  /**
   * Vocabulary the learner imported. Theirs, and in no app build — so it is the
   * part of a deck that is actually lost when a device is.
   *
   * @generated from field: repeated mon.v1.LexicalEntry entries = 4;
   */
  entries: LexicalEntry[];

  /**
   * @generated from field: repeated mon.v1.ReviewLogEntry reviews = 5;
   */
  reviews: ReviewLogEntry[];

  /**
   * Send this as `since` next time. Opaque on purpose; it happens to be a
   * timestamp today and a client that parses it will break when it is not.
   *
   * @generated from field: string cursor = 6;
   */
  cursor: string;

  /**
   * More reviews are waiting beyond `limit`. Pull again with the new cursor.
   *
   * @generated from field: bool more = 7;
   */
  more: boolean;
};

